package com.chesspulseai.service; import com.chesspulseai.enumtype.GamePhase; import org.springframework.stereotype.Service;
/** Position classifier: endgames have no queens or materially reduced non-pawn forces; opening requires substantial undeveloped material and central pawn structure. */ @Service public class GamePhaseDetector { public GamePhase detect(String fen){String p=fen.split(" ")[0];int q=count(p,"qQ"),r=count(p,"rR"),minor=count(p,"bBnN"),pawns=count(p,"pP");int developed=minor+2*r+4*q;if(q==0&&(r<=2||minor<=4))return GamePhase.ENDGAME;if(developed<=8&&pawns<=10)return GamePhase.ENDGAME;if(q==2&&minor>=6&&pawns>=12&&isOpeningStructure(p))return GamePhase.OPENING;return GamePhase.MIDDLEGAME;} private int count(String s,String chars){int n=0;for(char c:s.toCharArray())if(chars.indexOf(c)>=0)n++;return n;} private boolean isOpeningStructure(String p){return p.contains("PPPP")||p.contains("pppp");}}

